<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Models\{User,Hazard,HomeGalleryGroup,HomeGalleryPhoto,HazardType};
use App\Services\HomeGalleryService;
use Carbon\CarbonImmutable;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\{Storage,DB};
class HomeGalleryTest extends TestCase {
 use DatabaseTransactions;
 protected function setUp():void {if(getenv('RUTEAMAN_SPATIAL_TESTS')!=='1')$this->markTestSkipped('Dedicated spatial test database required.');parent::setUp();$this->seed(\Database\Seeders\DemoSeeder::class);Storage::fake('local');}
 private function owner():User{$u=(new User)->forceFill(['display_name'=>'Gallery Owner','email'=>'gallery-owner@test.invalid','password'=>'FixturePassword123!','active'=>true,'role'=>'owner','status'=>'active','permissions'=>[]]);$u->save();return $u;}
 private function loginOwner():User{$u=$this->owner();$this->actingAs($u)->withSession(['admin.reauth_at'=>time(),'admin.last_seen'=>time()]);return $u;}
 private function group(string $key='routes'):HomeGalleryGroup{return HomeGalleryGroup::where('key',$key)->firstOrFail();}
 private function settings(array $overrides=[]):array{return [...['orientation'=>'landscape','source'=>'admin','mode'=>'stay','interval_value'=>30,'interval_unit'=>'seconds','fixed_token'=>'','school_id'=>'','category_ids'=>[]],...$overrides];}
 private function upload(string $key='routes',int $w=800,int $h=500):HomeGalleryPhoto{$g=$this->group($key);$this->post(route('admin.home-gallery.upload',$g),['photo'=>UploadedFile::fake()->image('photo.jpg',$w,$h),'caption'=>'Ilustrasi genangan','type_id'=>HazardType::where('code','flood')->value('id'),'sort_order'=>0,'publication_consent'=>1])->assertRedirect(route('admin.home-gallery'));return HomeGalleryPhoto::where('group_id',$g->id)->latest()->firstOrFail();}
 public function test_public_feed_three_groups_with_no_private_metadata():void{$this->get('/api/home-gallery')->assertOk()->assertHeader('Cache-Control','no-store, private')->assertJsonCount(3,'groups')->assertDontSee('photo_path')->assertDontSee('guest_name')->assertDontSee('uploaded_by');$this->get('/')->assertOk()->assertSee('data-home-gallery="routes"',false)->assertSee('data-home-gallery="reporting"',false)->assertSee('data-home-gallery="followup"',false);}
 public function test_only_owner_can_read_and_write_gallery():void{$this->get('/admin/home-gallery')->assertRedirect(route('login'));$u=User::where('email','admin_a@ruteaman.test')->firstOrFail();$this->actingAs($u)->get('/admin/home-gallery')->assertForbidden();$this->patch(route('admin.home-gallery.settings',$this->group()),$this->settings())->assertForbidden();$this->loginOwner();$this->get('/admin/home-gallery')->assertOk()->assertSee('Foto Beranda');}
 public function test_reauthentication_is_required_for_writes():void{$this->actingAs($this->owner());$this->patchJson(route('admin.home-gallery.settings',$this->group()),$this->settings())->assertStatus(428);}
 public function test_uploaded_photo_is_sanitized_private_and_groups_are_independent():void{$this->loginOwner();$p=$this->upload();$this->assertTrue(Storage::disk('local')->exists($p->path));$this->assertSame('image/webp',getimagesize(Storage::disk('local')->path($p->path))['mime']);$this->assertSame('landscape',$p->orientation);$this->assertStringNotContainsString('photo.jpg',$p->path);$gallery=app(HomeGalleryService::class);$this->assertContains('admin-'.$p->id,array_column($gallery->pool($this->group()),'token'));$this->assertNotContains('admin-'.$p->id,array_column($gallery->pool($this->group('reporting')),'token'));}
 public function test_upload_rejects_wrong_orientation_missing_consent_and_invalid_images():void{$this->loginOwner();$g=$this->group('reporting');$d=['photo'=>UploadedFile::fake()->image('wide.jpg',800,500),'caption'=>'Ilustrasi','sort_order'=>0,'publication_consent'=>1];$this->post(route('admin.home-gallery.upload',$g),$d)->assertSessionHasErrors('photo');$d['photo']=UploadedFile::fake()->image('tall.jpg',500,800);unset($d['publication_consent']);$this->post(route('admin.home-gallery.upload',$g),$d)->assertSessionHasErrors('publication_consent');$d['publication_consent']=1;$d['photo']=UploadedFile::fake()->create('script.svg',1,'image/svg+xml');$this->post(route('admin.home-gallery.upload',$g),$d)->assertSessionHasErrors('photo');$this->assertSame(0,HomeGalleryPhoto::count());}
 public function test_portrait_never_uses_report_photos_and_settings_validate_units():void{$this->loginOwner();$g=$this->group('reporting');$this->patch(route('admin.home-gallery.settings',$g),$this->settings(['orientation'=>'portrait','source'=>'mixed']))->assertSessionHasErrors('source');$this->patch(route('admin.home-gallery.settings',$g),$this->settings(['interval_unit'=>'year']))->assertSessionHasErrors('interval_unit');$this->patch(route('admin.home-gallery.settings',$g),$this->settings(['interval_value'=>0]))->assertSessionHasErrors('interval_value');}
 public function test_verified_landscape_only_excludes_demo_rejected_and_pending():void{$g=$this->group();$g->forceFill(['source'=>'verified','fixed_token'=>null])->save();$service=app(HomeGalleryService::class);$h=Hazard::where('public_slug','demo-lubang-jl-mawar')->firstOrFail();$r=$h->reports()->orderByDesc('id')->first();$token='report-'.$r->id;$this->assertNotContains($token,array_column($service->pool($g),'token'));$h->forceFill(['is_demo'=>false,'published_at'=>now(),'last_confirmed_at'=>now()])->save();$this->assertContains($token,array_column($service->pool($g),'token'));$url=route('home-gallery.media',[$g->key,$token]);$this->get($url)->assertOk()->assertHeader('Content-Type','image/webp')->assertHeader('Cache-Control','no-store, private');$h->forceFill(['requires_moderation'=>true])->save();$this->get($url)->assertNotFound();$h->forceFill(['requires_moderation'=>false])->save();$h->verifications()->create(['verifier_id'=>User::where('email','admin_a@ruteaman.test')->value('id'),'decision'=>'rejected','created_at'=>now()]);$this->get($url)->assertNotFound();}
 public function test_photo_hide_delete_and_source_changes_revoke_media():void{$this->loginOwner();$p=$this->upload();$url=route('home-gallery.media',['routes','admin-'.$p->id]);$this->get($url)->assertOk();$this->patch(route('admin.home-gallery.photo',$p),['caption'=>'Ilustrasi baru','type_id'=>'','sort_order'=>1,'enabled'=>0])->assertRedirect();$this->get($url)->assertNotFound();$this->get(route('admin.home-gallery.preview',$p))->assertOk();$this->delete(route('admin.home-gallery.delete',$p))->assertRedirect();$this->assertFalse(Storage::disk('local')->exists($p->path));$this->get($url)->assertNotFound();}
 public function test_filter_categories_and_fixed_photo_are_persisted():void{$this->loginOwner();$p=$this->upload();$g=$this->group();$this->patch(route('admin.home-gallery.settings',$g),$this->settings(['fixed_token'=>'admin-'.$p->id]))->assertRedirect();$this->assertSame('admin-'.$p->id,$g->fresh()->fixed_token);$type=HazardType::where('code','pothole')->value('id');$this->patch(route('admin.home-gallery.settings',$g),$this->settings(['category_ids'=>[$type]]))->assertRedirect();$this->assertNotContains('admin-'.$p->id,array_column(app(HomeGalleryService::class)->pool($g->fresh()),'token'));$this->patch(route('admin.home-gallery.settings',$g),$this->settings(['fixed_token'=>'admin-no-such-photo']))->assertSessionHasErrors('fixed_token');}
 public function test_stay_and_all_time_units_including_calendar_months():void{$s=app(HomeGalleryService::class);$g=$this->group();$g->rotation_anchor=CarbonImmutable::parse('2026-01-31 10:00:00','Asia/Jakarta')->utc();$g->mode='stay';$this->assertNull($s->timing($g)['next']);$g->mode='rotate';$g->interval_value=2;foreach(['seconds'=>1,'minutes'=>60,'hours'=>3600,'days'=>86400,'weeks'=>604800] as $unit=>$seconds){$g->interval_unit=$unit;$at=$g->rotation_anchor->addSeconds($seconds*5);$t=$s->timing($g,$at);$this->assertSame(2,$t['index']);$this->assertSame($g->rotation_anchor->addSeconds($seconds*6)->setTimezone('Asia/Jakarta')->toIso8601String(),$t['next']);}$g->interval_value=1;$g->interval_unit='months';$t=$s->timing($g,CarbonImmutable::parse('2026-02-28 10:00:00','Asia/Jakarta'));$this->assertSame(1,$t['index']);$this->assertSame('2026-03-31T10:00:00+07:00',$t['next']);}
 public function test_stay_auto_selects_one_photo_and_does_not_follow_new_uploads():void{$this->loginOwner();$p=$this->upload();$g=$this->group();$this->patch(route('admin.home-gallery.settings',$g),$this->settings())->assertRedirect();$before=app(HomeGalleryService::class)->feed()['groups']['routes']['frames'][1]['token'];$this->upload();$after=app(HomeGalleryService::class)->feed()['groups']['routes']['frames'][1]['token'];$this->assertSame($before,$after);}
}
